Here is the commit message:
tpm: tpm_i2c_infineon: Fix locality leak on get_burstcount()
 failure

get_burstcount() can return -EBUSY on timeout. When this happens, the
function returns directly without releasing the locality that was
acquired at the beginning of tpm_tis_i2c_send().

Use goto out_err to ensure proper cleanup when get_burstcount() fails.

Fixes: aad628c1d91a ("char/tpm: Add new driver for Infineon I2C TIS TPM")
Signed-off-by: Alper Ak <alperyasinak1@gmail.com>
Reviewed-by: Jarkko Sakkinen <jarkko@kernel.org>
Signed-off-by: Jarkko Sakkinen <jarkko@kernel.org>

Here is the root cause:
In `tpm_tis_i2c_send()`, after acquiring a locality, if `get_burstcount()` returns a negative value (e.g., -EBUSY on timeout), the function returns the error directly without releasing the locality, causing a resource leak.

Here is the patch:

 static int tpm_tis_i2c_send(struct tpm_chip *chip, u8 *buf, size_t bufsiz,
 			    size_t len)
 {
 	int rc, status;
 	ssize_t burstcnt;
 	size_t count = 0;
 	u8 retries = 0;
 	u8 sts = TPM_STS_GO;

 	if (len > TPM_I2C_INFINEON_BUFSIZE)
 		return -E2BIG;

 	if (request_locality(chip, 0) < 0)
 		return -EBUSY;

 	status = tpm_tis_i2c_status(chip);
 	if ((status & TPM_STS_COMMAND_READY) == 0) {
 		tpm_tis_i2c_ready(chip);
 		if (wait_for_stat
 		    (chip, TPM_STS_COMMAND_READY,
 		     chip->timeout_b, &status) < 0) {
 			rc = -ETIME;
 			goto out_err;
 		}
 	}

 	while (count < len - 1) {
 		burstcnt = get_burstcount(chip);

 		/* burstcnt < 0 = TPM is busy */
-		if (burstcnt < 0)
-			return burstcnt;
+		if (burstcnt < 0) {
+			rc = burstcnt;
+			goto out_err;
+		}

 		if (burstcnt > (len - 1 - count))
 			burstcnt = len - 1 - count;

 		rc = iic_tpm_write(TPM_DATA_FIFO(tpm_dev.locality),
 				   &(buf[count]), burstcnt);
 		if (rc == 0)
 			count += burstcnt;
 		else if (rc < 0)
 			retries++;

 		/* avoid endless loop in case of broken HW */
 		if (retries > MAX_COUNT_LONG) {
 			rc = -EIO;
 			goto out_err;
 		}

 		wait_for_stat(chip, TPM_STS_VALID,
 			      chip->timeout_c, &status);

 		if ((status & TPM_STS_DATA_EXPECT) == 0) {
 			rc = -EIO;
 			goto out_err;
 		}
 	}

 	/* write last byte */
 	iic_tpm_write(TPM_DATA_FIFO(tpm_dev.locality), &(buf[count]), 1);
 	wait_for_stat(chip, TPM_STS_VALID, chip->timeout_c, &status);
 	if ((status & TPM_STS_DATA_EXPECT) != 0) {
 		rc = -EIO;
 		goto out_err;
 	}

 	/* go and do it */
 	iic_tpm_write(TPM_STS(tpm_dev.locality), &sts, 1);

 	return 0;
 out_err:
 	tpm_tis_i2c_ready(chip);
 	/* The TPM needs some time to clean up here,
 	 * so we sleep rather than keeping the bus busy
 	 */
 	usleep_range(SLEEP_DURATION_RESET_LOW, SLEEP_DURATION_RESET_HI);
 	release_locality(chip, tpm_dev.locality, 0);
 	return rc;
 }



